import { WaveManager } from '../wave-manager/wave-manager.ts';

export class EnemyAI {
  private currentState: 'idle' | 'attacking' = 'idle';
  private enemyPosition: { x: number; y: number } = { x: 0, y: 0 };

  constructor() {}

  manageWaves(): void {
    console.log('Enemy AI managing waves.');
  }

  move(): void {
    if (this.currentState === 'idle') {
      const randomX = Math.floor(Math.random() * 128);
      const randomY = Math.floor(Math.random() * 70);
      this.enemyPosition = { x: randomX, y: randomY };
      this.currentState = 'attacking';
    }
  }

  attack(): void {
    if (this.currentState === 'attacking') {
      console.log('Enemy AI attacking!');
      this.currentState = 'idle';
    }
  }
}

import { EnemyAI } from '../enemy-ai/enemy-ai.ts';

export interface CombatEngine {
  handleCombatRequest(request: { shipHealth: number; enemyDamage: number }): void;
  manageEnemyAI(): void;
}

export class CombatEngineImpl implements CombatEngine {
  private shipHealth: number = 100;
  private enemyDamage: number = 0;
  private enemyPosition: { x: number; y: number } = { x: 0, y: 0 };

  constructor() {}

  handleCombatRequest(request: { shipHealth: number; enemyDamage: number }): void {
    this.shipHealth = request.shipHealth;
    this.enemyDamage = request.enemyDamage;
    this.manageEnemyAI();
  }

  manageEnemyAI(): void {
    const enemyHealth = 100;
    const damage = 10;
    this.shipHealth -= damage;
    this.enemyDamage += damage;
    this.enemyPosition = { x: 50, y: 30 };
    console.log(`Enemy AI managing combat: Ship Health ${this.shipHealth}, Enemy Health ${enemyHealth}, Damage ${damage}`);
  }
}

